import Title = require( './index' );


// TESTS //

// The function returns a title instance...
{
	new Title(); // $ExpectType Title
	new Title( {} ); // $ExpectType Title
	new Title( { 'text': 'Beep boop' } ); // $ExpectType Title
	new Title( { 'text': 'Beep boop', 'anchor': 'start', 'orient': 'bottom' } ); // $ExpectType Title

	Title(); // $ExpectType Title
	Title( {} ); // $ExpectType Title
	Title( { 'text': 'Beep boop' } ); // $ExpectType Title
	Title( { 'text': 'Beep boop', 'anchor': 'start', 'orient': 'bottom' } ); // $ExpectType Title
}

// The compiler throws an error if the function is provided an options argument which is not an object...
{
	new Title( '5' ); // $ExpectError
	new Title( 5 ); // $ExpectError
	new Title( true ); // $ExpectError
	new Title( false ); // $ExpectError
	new Title( null ); // $ExpectError
	new Title( [] ); // $ExpectError
	new Title( ( x: number ): number => x ); // $ExpectError

	Title( '5' ); // $ExpectError
	Title( 5 ); // $ExpectError
	Title( true ); // $ExpectError
	Title( false ); // $ExpectError
	Title( null ); // $ExpectError
	Title( [] ); // $ExpectError
	Title( ( x: number ): number => x ); // $ExpectError
}

