// A title instance has title properties...
{
	const title = new Title();

	const align = title.align; // $ExpectType string | undefined
	const anchor = title.anchor; // $ExpectType AnchorPosition
	const angle = title.angle; // $ExpectType number | undefined
	const aria = title.aria; // $ExpectType boolean
	const baseline = title.baseline; // $ExpectType VerticalBaseline | undefined
	const color = title.color; // $ExpectType string | undefined
	const dx = title.dx; // $ExpectType number | undefined
	const dy = title.dy; // $ExpectType number | undefined
	const encode = title.encode; // $ExpectType any
	const font = title.font; // $ExpectType string | undefined
	const fontSize = title.fontSize; // $ExpectType number | undefined
	const fontStyle = title.fontStyle; // $ExpectType FontStyle | undefined
	const fontWeight = title.fontWeight; // $ExpectType FontWeight | undefined
	const frame = title.frame; // $ExpectType ReferenceFrame
	const limit = title.limit; // $ExpectType number | undefined
	const lineHeight = title.lineHeight; // $ExpectType number | undefined
	const offset = title.offset; // $ExpectType number | undefined
	const orient = title.orient; // $ExpectType Orientation
	const subtitle = title.subtitle; // $ExpectType string[] | undefined
	const subtitleColor = title.subtitleColor; // $ExpectType string | undefined
	const subtitleFont = title.subtitleFont; // $ExpectType string | undefined
	const subtitleFontSize = title.subtitleFontSize; // $ExpectType number | undefined
	const subtitleFontStyle = title.subtitleFontStyle; // $ExpectType string | undefined
	const subtitleFontWeight = title.subtitleFontWeight; // $ExpectType string | number | undefined
	const subtitleLineHeight = title.subtitleLineHeight; // $ExpectType number | undefined
	const subtitlePadding = title.subtitlePadding; // $ExpectType number | undefined
	const text = title.text; // $ExpectType string[]
	const zindex = title.zindex; // $ExpectType number

	const values = [
		align,
		anchor,
		angle,
		aria,
		baseline,
		color,
		dx,
		dy,
		encode,
		font,
		fontSize,
		fontStyle,
		fontWeight,
		frame,
		limit,
		lineHeight,
		offset,
		orient,
		subtitle,
		subtitleColor,
		subtitleFont,
		subtitleFontSize,
		subtitleFontStyle,
		subtitleFontWeight,
		subtitleLineHeight,
		subtitlePadding,
		text,
		zindex
	];
	if ( values.length !== 28 ) {
		throw new Error( 'unexpected error' );
	}
}

// The compiler throws an error if a title property is assigned an unsupported value...
{
	const title = new Title();

	title.align = 5; // $ExpectError
	title.anchor = 'abc'; // $ExpectError
	title.aria = '5'; // $ExpectError
	title.fontSize = '5'; // $ExpectError
	title.subtitle = 5; // $ExpectError
	title.text = 5; // $ExpectError
}

// A title instance has a read-only `properties` property...
{
	const title = new Title();

	const props = title.properties; // $ExpectType string[]
	if ( props.length !== 28 ) {
		throw new Error( 'unexpected error' );
	}
	title.properties = [ 'text' ]; // $ExpectError
}

// A title instance has a `toJSON` method which returns a JSON object...
{
	const title = new Title();

	title.toJSON(); // $ExpectType JSON
}

// The compiler throws an error if the `toJSON` method is provided arguments...
{
	const title = new Title();

	title.toJSON( {} ); // $ExpectError
}
